 double y[1025],jac[1025],h[1025],jv[1025],vj[1025],jy[1025],hjv[1025],v[16],cot[1025],hcot[1025];for(int j=0;j<d;j++)v[j]=(j%5-2)*.25;for(int j=0;j<n*d;j++)hcot[j]=(j%7-3)*.125;for(int j=0;j<n;j++)cot[j]=(j%5-2)*.5;
 coax_t_FxWork w=work();coax_t_FxRun r=fx_eval(f,(coax_v_f32){x,d},(coax_v_f64){y,1025},w,0);CHECK(!r.status&&r.values==n);if(id==10)CHECK(signbit(y[0])==signbit(x[0]));CHECK(!fx_eval(jb.function,(coax_v_f32){x,d},(coax_v_f64){jac,1025},w,0).status);CHECK(!fx_eval(hb.function,(coax_v_f32){x,d},(coax_v_f64){h,1025},w,0).status);
 r=fx_jvp(f,(coax_v_f32){x,d},(coax_v_f64){v,d},(coax_v_f64){jy,1025},(coax_v_f64){jv,1025},w,0);CHECK(!r.status&&r.values==n&&r.derivatives==n);for(int i=0;i<n;i++){close_to(jy[i],y[i]);double expected=0;for(int j=0;j<d;j++)expected+=jac[i*d+j]*v[j];close_to(jv[i],expected);}
