 for(int which=0;which<9;which++){coax_t_FxWork z=w;switch(which){case 0:z.values.count=0;break;case 1:z.flags.count=0;break;case 2:z.dots.count=0;break;case 3:z.grads.count=0;break;case 4:z.grad_dots.count=0;break;case 5:z.seed.count=0;break;case 6:z.direction.count=0;break;case 7:z.stage.count=0;break;case 8:z.point.count=0;break;}CHECK(fx_eval(f,(coax_v_f32){x,d},(coax_v_f64){y,16},z,0).status==COAX_FxStatus_capacity);}
