 uint32_t bits=0x7fc00001;memcpy(x+2,&bits,4);CHECK(fx_eval(f,(coax_v_f32){x,d},(coax_v_f64){y,16},w,0).status==COAX_FxStatus_number);x[2]=2;seed[2]=NAN;CHECK(fx_jvp(f,(coax_v_f32){x,d},(coax_v_f64){seed,d},(coax_v_f64){y,16},(coax_v_f64){dy,16},w,0).status==COAX_FxStatus_number);seed[2]=3;seed[0]=NAN;CHECK(fx_vjp(f,(coax_v_f32){x,d},(coax_v_f64){seed,1},(coax_v_f64){y,16},(coax_v_f64){dy,16},w,0).status==COAX_FxStatus_number);
