 p.nodes.e[0].placement=COAX_TiPlacement_cuda;CHECK(fx_function(p).status==COAX_FxStatus_program);p=program(0,x,&d,&n);p.nodes.e[1]=op(COAX_TiOp_registered,0,0,0);CHECK(fx_function(p).status==COAX_FxStatus_operation);p.count=1;p.output=0;p.nodes.e[0]=ti_input(shape(257,0),0);CHECK(fx_function(p).status==COAX_FxStatus_limit);
