 for(int i=0;i<20;i++)out[i]=777;rows[9]=NAN;CHECK(fx_vmap_apply(b.map,(coax_v_f32){shared,d},(coax_v_f32){rows,12},(coax_v_f64){out,20},work(),0).status==COAX_FxStatus_number);for(int i=0;i<20;i++)CHECK(out[i]==777);rows[9]=-1;
 CHECK(fx_vmap(f,(coax_v_s64){axes,d},0).status==COAX_FxStatus_shape&&fx_vmap(f,(coax_v_s64){axes,d},65).status==COAX_FxStatus_shape&&fx_vmap(f,(coax_v_s64){axes,d-1},3).status==COAX_FxStatus_shape);axes[2]=1;CHECK(fx_vmap(f,(coax_v_s64){axes,d},3).status==COAX_FxStatus_shape);axes[2]=-2;CHECK(fx_vmap(f,(coax_v_s64){axes,d},3).status==COAX_FxStatus_shape);
 CHECK(fx_vmap_apply(b.map,(coax_v_f32){shared,d-1},(coax_v_f32){rows,12},(coax_v_f64){out,20},work(),0).status==COAX_FxStatus_shape);CHECK(fx_vmap_apply(b.map,(coax_v_f32){shared,d},(coax_v_f32){rows,11},(coax_v_f64){out,20},work(),0).status==COAX_FxStatus_shape);CHECK(fx_vmap_apply(b.map,(coax_v_f32){shared,d},(coax_v_f32){rows,12},(coax_v_f64){out,11},work(),0).status==COAX_FxStatus_capacity);CHECK(fx_vmap_apply(b.map,(coax_v_f32){shared,d},(coax_v_f32){rows,12},(coax_v_f64){out,20},work(),1).status==COAX_FxStatus_alias);
