static void budget_refusal(void){
 coax_t_TiProgram p={0};p.count=4;p.output=3;p.nodes.e[0]=ti_input(shape(16,16),0);p.nodes.e[1]=op(COAX_TiOp_matmul,0,0,0);p.nodes.e[2]=op(COAX_TiOp_sum,1,0,1);p.nodes.e[3]=op(COAX_TiOp_sum,2,0,0);coax_t_FxBuild f=fx_function(p),g=fx_grad(f.function);CHECK(!f.status&&!g.status&&g.function.count==256);int64_t axes[256]={0};CHECK(fx_vmap(g.function,(coax_v_s64){axes,256},64).status==COAX_FxStatus_limit);static float shared[256],rows[16384];coax_t_FxMapped m={.function=g.function,.batch=64};double out[20];for(int i=0;i<20;i++)out[i]=777;CHECK(fx_vmap_apply(m,(coax_v_f32){shared,256},(coax_v_f32){rows,16384},(coax_v_f64){out,20},work(),0).status==COAX_FxStatus_limit);for(int i=0;i<20;i++)CHECK(out[i]==777);
}
